<style>
.package-editor{--p-bg:#fff;--p-soft:#f1f5f9;--p-text:#0f172a;--p-muted:#475569;--p-line:#cbd5e1;--p-brand:#0e7490;max-width:960px;margin:auto;display:grid;gap:22px;color:var(--p-text)}.dark .package-editor{--p-bg:#151e30;--p-soft:#202c40;--p-text:#edf2f7;--p-muted:#b8c5d6;--p-line:#41516a;--p-brand:#67e8f9}.p-head h1{font-size:25px;font-weight:800;margin:8px 0}.p-head a{color:var(--p-brand);font-size:13px;text-decoration:none}.p-note{font-size:13px;line-height:1.7;color:var(--p-muted)}.p-panel{background:var(--p-bg);border:1px solid var(--p-line);border-radius:18px;padding:22px;margin-bottom:18px}.p-panel h2{font-size:16px;font-weight:750;color:var(--p-text);margin-bottom:8px}.p-fields{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:18px}.p-field{display:block;font-size:13px;font-weight:600;color:var(--p-text)}.p-field input{display:block;box-sizing:border-box;width:100%;margin-top:8px;padding:12px 14px;border:1px solid var(--p-line);border-radius:11px;background:var(--p-bg);color:var(--p-text);font-size:14px;font-weight:400;outline:none}.p-field input:focus{border-color:#0891b2;box-shadow:0 0 0 3px #0891b230}.p-field input::placeholder{color:var(--p-muted)}.p-router-list{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:18px}.p-router{display:flex;align-items:flex-start;gap:12px;padding:16px;border:1px solid var(--p-line);border-radius:12px;background:var(--p-soft);cursor:pointer}.p-router input{margin-top:4px;width:17px;height:17px;accent-color:#0891b2;flex-shrink:0}.p-router strong{display:block;font-size:14px;color:var(--p-text)}.p-router small{display:block;font-size:11px;line-height:1.6;color:var(--p-muted);margin-top:4px}.p-error{font-size:12px;color:#be123c;line-height:1.6;margin-top:6px}.dark .p-error{color:#fecdd3}.p-error-box{padding:16px;border:1px solid #fb7185;border-radius:12px;background:#fff1f2;color:#9f1239;font-size:13px}.dark .p-error-box{background:#3d202e;color:#fecdd3}.p-actions{display:flex;gap:12px;flex-wrap:wrap;align-items:center}.p-btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:12px 18px;border:1px solid var(--p-line);border-radius:11px;background:var(--p-bg);color:var(--p-text);font-size:13px;font-weight:650;cursor:pointer;text-decoration:none}.p-btn-primary{background:#0e7490;color:#fff;border-color:#0e7490}.p-btn-primary:hover{background:#155e75}.p-btn:focus-visible{outline:3px solid #22d3ee;outline-offset:2px}.p-btn:disabled{opacity:.5;cursor:not-allowed}.p-panel summary{cursor:pointer;font-weight:650;font-size:14px;color:var(--p-text)}.p-hint{padding:14px 16px;background:var(--p-soft);border:1px solid var(--p-line);border-radius:12px;font-size:12px;line-height:1.7;color:var(--p-muted)}.router-flash-success{background:#ecfdf5!important;color:#065f46!important;border-color:#6ee7b7!important}.dark .router-flash-success{background:#12382c!important;color:#bbf7d0!important;border-color:#438b68!important}.router-flash-error{background:#fff1f2!important;color:#9f1239!important;border-color:#fda4af!important}.dark .router-flash-error{background:#3d202e!important;color:#fecdd3!important;border-color:#9b5064!important}@media(max-width:650px){.p-fields,.p-router-list{grid-template-columns:1fr}.p-panel{padding:18px}.p-head h1{font-size:22px}}
</style>
